<?php declare(strict_types=1);
$ift=static fn(string$s,array$v=[]):string=>\Kulturhus\Native\Language\InventoryFileMessages::text($s,$managerLanguageMessages??[],$v);$files=$inventory->files($itemId);$fileState=$inventoryFileState;$fileRoute=$fileState['route'];$fileRecovery=$fileRoute+['file_recheck'=>bin2hex(random_bytes(6))];$filePosted=input($_POST,'action')==='inventory-file';$fileUrl=url($fileRoute+['file_request'=>$fileState['key']??'']).'#inventory-item-files';
?>
<link rel="stylesheet" href="inventory-files.css?v=1"><details id="inventory-item-files" class="iv-editor-panel iv-item-files" data-inventory-panel="files" <?= $filePosted||array_key_exists('file_request',$_GET)?'open':'' ?>><summary><span><strong><?= e($ift('Fotos & weitere Dokumente')) ?></strong><small><?= e($ift('{count} Dateien beim Gegenstand · Fotos, Anleitungen und Nachweise',['count'=>(string)count($files)])) ?></small></span></summary><div class="iv-editor-body">
<?php if($fileState['original']!==null&&($error!==''||$fileState['blocked'])): ?><section class="card" data-inventory-file-original><h2><?= e($ift('Dateiauftrag')) ?></h2><p><?= e($ift('Die vollständigen bekannten Angaben bleiben zur Prüfung sichtbar. Es wird keine andere Datei oder Gegenstandszuordnung eingesetzt.')) ?></p><pre><?= e(json_encode($fileState['original'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_THROW_ON_ERROR)) ?></pre><a class="btn btn-outline theme-secondary" href="<?= e(url($fileRecovery).'#inventory-item-files') ?>"><?= e($ift('Gegenstand und Dateizuordnung neu prüfen')) ?></a></section><?php endif ?>
<?php if($fileState['saved']!==null):$savedFile=$fileState['saved']; ?><section class="card" data-inventory-file-saved data-document-id="<?= e($savedFile['id']) ?>"><h2><?= e($ift('Dieser Dateianhang wurde bereits gespeichert.')) ?></h2><p><?= e($ift('Die vorhandene Datei bleibt zugeordnet. Eine Wiederholung legt keinen zweiten Anhang an.')) ?></p><a class="btn btn-outline theme-secondary" href="<?= e(url(['inventory_asset'=>$savedFile['id'],'download'=>'1'])) ?>"><?= e($ift('Gespeicherte Datei öffnen: {name}',['name'=>$savedFile['name']])) ?></a><?php if($ivWrite): ?><a class="btn btn-outline theme-secondary" href="<?= e(url($fileRecovery).'#inventory-item-files') ?>"><?= e($ift('Weiteren Dateianhang vorbereiten')) ?></a><?php endif ?></section><?php endif ?>
<div class="iv-files"><?php foreach($files as$f): ?><a href="<?= e(url(['inventory_asset'=>$f['id'],'download'=>'1'])) ?>" class="iv-file" data-inventory-file-id="<?= e($f['id']) ?>"><?php if(str_starts_with($f['mime'],'image/')): ?><img loading="lazy" src="<?= e(url(['inventory_asset'=>$f['id']])) ?>" alt="<?= e($f['name']) ?>"><?php else: ?><span><?= icon('file') ?> <?= e($ift('Datei')) ?></span><?php endif ?><strong><?= e($f['name']) ?></strong><small><?= e($ift('{size} KB · Herunterladen',['size'=>number_format($f['size']/1024,1,($managerLanguageMessages[\Kulturhus\Native\Language\InventoryFileMessages::key('Datei')]??'Datei')==='File'?'.':',','')])) ?></small></a><?php endforeach;if(!$files): ?><p><?= e($ift('Noch keine Fotos oder Nachweise hinterlegt.')) ?></p><?php endif ?></div>
<?php if($ivWrite&&!$fileState['blocked']&&$fileState['saved']===null): ?><form method="post" enctype="multipart/form-data" data-native-attachment data-inventory-file-form action="<?= e($fileUrl) ?>"><?= csrf().hidden('action','inventory-file').hidden('target',$itemId).hidden('version',$filePosted?$_POST['version']:(string)$item['version']).hidden('request_key',$fileState['key']) ?><h3><?= e($ift('Datei diesem Gegenstand zuordnen')) ?></h3><p><?= e($ift('Datei auswählen und anschließend bewusst hinzufügen. Die Auswahl allein speichert und überträgt nichts.')) ?></p><label><?= e($ift('Foto oder Nachweis (PNG, JPEG, PDF · max. 2 MB; HEIC/RAW bis 256 MiB werden als JPEG gespeichert)')) ?><input class="form-control" type="file" data-photo-server name="inventory_file" accept="image/png,image/jpeg,application/pdf,.heic,.heif,.hif,.dng,.cr2,.cr3,.crw,.nef,.nrw,.arw,.sr2,.srf,.rw2,.rwl,.orf,.raf,.pef,.ptx,.raw,.iiq,.3fr,.fff,.kdc,.dcr,.mos,.mef,.mrw,.erf" required></label><?php if($filePosted): ?><p role="status"><?= e($ift('Die Datei bleibt im Browser aus Datenschutzgründen nicht vorausgewählt. Zuerst den gespeicherten Stand prüfen; falls noch nicht gespeichert, dieselbe ursprüngliche Datei erneut auswählen.')) ?></p><?php endif ?><button class="btn btn-solid theme-primary"><?= e($ift('Datei hinzufügen')) ?></button><a class="btn btn-outline theme-secondary" href="<?= e($fileUrl) ?>"><?= e($ift('Gespeicherten Stand dieses Dateiauftrags prüfen')) ?></a><?= hidden('inventory_file_complete','1') ?></form><?php endif ?>
<?php documentPanel($documents,'item',$itemId); ?></div></details>
